"use client";

import type { ComponentProps } from "react";
import { useEffect, useState } from "react";

import { useSocialPostPreview } from "~/hooks/use-social-post-preview";
import { UserAvatar, UserAvatarBadge } from "~/components/user-avatar";
import { cn } from "~/lib/utils";
import { BrandMark } from "~/ui/brand-mark";
import { User } from "lucide-react";
import { Skeleton } from "~/ui/skeleton";
import { Toggle } from "~/ui/toggle";

import { SocialPostPreviewDevice } from "./social-post-preview-device";
import {
  SocialPostPreviewFrameProvider,
  useSocialPostPreviewFrame,
} from "./social-post-preview-context";
import { SocialPostPreviewFeed } from "./social-post-preview-feed-skeleton";
import { SocialPostPreviewMediaItem } from "./social-post-preview-media";
import { StoryRotator } from "./social-post-preview-story";
import type { SocialPostPreviewView } from "~/lib/social-post-preview-resolver";
import type {
  SocialPostPreviewDescriptor,
  SocialPostPreviewInput,
  SocialPostPreviewMedia,
} from "~/lib/social-post-preview-types";

import {
  TikTokPost,
  TikTokPostMedia,
  TikTokPostUI,
} from "~/ui/tiktok-chrome";
import { XPost, XPostMedia, XPostQuote } from "~/ui/x-chrome";
import {
  InstagramPost,
  InstagramPostMedia,
  InstagramReel,
  InstagramReelMedia,
  InstagramReelUI,
  InstagramStory,
  InstagramStoryMedia,
  InstagramStoryUI,
} from "~/ui/instagram-chrome";
import {
  FacebookPost,
  FacebookPostMedia,
  FacebookReel,
  FacebookReelMedia,
  FacebookReelUI,
  FacebookStory,
  FacebookStoryMedia,
  FacebookStoryUI,
} from "~/ui/facebook-chrome";
import {
  YouTubeShort,
  YouTubeShortMedia,
  YouTubeShortUI,
  YouTubeVideo,
  YouTubeVideoMedia,
} from "~/ui/youtube-chrome";
import { LinkedInPost, LinkedInPostMedia } from "~/ui/linkedin-chrome";
import { PinterestPin, PinterestPinMedia } from "~/ui/pinterest-chrome";
import { ThreadsPost, ThreadsPostMedia } from "~/ui/threads-chrome";
import { BlueskyPost, BlueskyPostMedia } from "~/ui/bluesky-chrome";

// ── The auto-renderer + its dispatcher — the full integration: hook (materialize + resolve),
// the config cascade, the device frame, the feed context, and the per-platform mapping. The
// raw building blocks live in the sibling `social-post-preview-*` files (device, context,
// feed, media) and in `~/ui/<platform>-chrome`; this file wires them together.

// The timeline platforms whose bare post the renderer drops into the shared feed context
// (a masked run of skeleton posts) so the device reads like a real feed. Full-bleed surfaces
// (reel / story / video), plus YouTube and Pinterest, render their bare chrome directly.
const FEED_CONTEXT_PLATFORMS = new Set([
  "x",
  "instagram",
  "facebook",
  "linkedin",
  "threads",
  "bluesky",
]);
function needsFeedContext(descriptor: SocialPostPreviewDescriptor): boolean {
  return (
    !descriptor.placeholder &&
    !!descriptor.platform &&
    FEED_CONTEXT_PLATFORMS.has(descriptor.platform) &&
    descriptor.surface === "feed"
  );
}

/** A device with the current frame's chrome inside — wrapped in the feed context if it's a feed. */
function SocialPostPreviewFramedDevice({
  descriptor,
}: {
  descriptor: SocialPostPreviewDescriptor;
}) {
  return (
    <SocialPostPreviewFrameProvider descriptor={descriptor}>
      <SocialPostPreviewDevice>
        {needsFeedContext(descriptor) ? (
          <SocialPostPreviewFeed>
            <SocialPostPreviewChrome />
          </SocialPostPreviewFeed>
        ) : (
          <SocialPostPreviewChrome />
        )}
      </SocialPostPreviewDevice>
    </SocialPostPreviewFrameProvider>
  );
}

/**
 * The opinionated, Post-for-Me-native entry point — the **model citizen** for previewing
 * a social post. Hand it a PFM {@link SocialPostPreviewInput} (a real `SocialPost` works
 * as-is) and it does everything: applies the full configuration cascade per account, then
 * renders each targeted account's frame. This is the full integration; to take control, drop
 * to the per-platform chrome primitives in `~/ui/<platform>-chrome`.
 *
 * Three displays:
 * - `"auto"` (default) — **decides for you**: with more than one distinct preview it shows one
 *   frame plus a **switcher** (a row of platform-default renderings + a row of account
 *   overrides); with a single option it shows just that one frame, no switcher.
 * - `"toggle"` — always the single-frame + switcher UI.
 * - `"grid"` — fans out every targeted account frame at once, no switcher.
 */
export function SocialPostPreview({
  post,
  display = "auto",
  className,
  ...props
}: {
  post: SocialPostPreviewInput;
  display?: "auto" | "grid" | "toggle";
} & Omit<ComponentProps<"div">, "children">) {
  // The headless engine: materializes local files → object URLs and resolves the config
  // cascade into descriptors + the distinct views.
  const { descriptors, views } = useSocialPostPreview(post);
  const [activeKey, setActiveKey] = useState<string | null>(null);

  // "grid" fans out every account frame side by side.
  if (display === "grid") {
    return (
      <div
        data-slot="social-post-preview"
        data-display="grid"
        className={cn(
          "grid grid-cols-[repeat(auto-fill,minmax(15rem,1fr))] items-start gap-4",
          className,
        )}
        {...props}
      >
        {descriptors.map((descriptor) => (
          <SocialPostPreviewFramedDevice
            key={descriptor.id}
            descriptor={descriptor}
          />
        ))}
      </div>
    );
  }

  // The switcher appears whenever there's more than one distinct preview — automatically in
  // "auto", always in "toggle".
  const showSwitcher = display === "toggle" || views.length > 1;

  if (showSwitcher) {
    const activeView =
      views.find((view) => view.key === activeKey) ?? views[0] ?? null;
    const platformViews = views.filter((view) => view.kind === "platform");
    const accountViews = views.filter((view) => view.kind === "account");

    return (
      <div
        data-slot="social-post-preview"
        data-display="toggle"
        className={cn("space-y-2", className)}
        {...props}
      >
        {activeView ? (
          <div className="mx-auto w-full max-w-56">
            <SocialPostPreviewFramedDevice descriptor={activeView.descriptor} />
          </div>
        ) : null}

        {/* Rows UNDER the preview — row 1: platform-default views, row 2: overrides. */}
        <div className="space-y-1">
          <ViewToggleRow
            label="Platforms"
            views={platformViews}
            activeKey={activeView?.key}
            onSelect={setActiveKey}
          />
          {accountViews.length ? (
            <ViewToggleRow
              label="Account overrides"
              views={accountViews}
              activeKey={activeView?.key}
              onSelect={setActiveKey}
            />
          ) : null}
        </div>
      </div>
    );
  }

  // "auto" with a single distinct preview — just the one framed device, no switcher.
  const only = views[0] ?? null;
  return (
    <div
      data-slot="social-post-preview"
      data-display="single"
      className={cn(className)}
      {...props}
    >
      {only ? (
        <SocialPostPreviewFramedDevice descriptor={only.descriptor} />
      ) : null}
    </div>
  );
}

/** One row of view chips (a platform row or an account-override row). */
function ViewToggleRow({
  label,
  views,
  activeKey,
  onSelect,
}: {
  activeKey?: string;
  label: string;
  onSelect: (key: string) => void;
  views: SocialPostPreviewView[];
}) {
  if (!views.length) return null;
  return (
    <div
      role="group"
      aria-label={label}
      className="flex flex-wrap justify-center gap-1"
    >
      {views.map((view) => (
        <Toggle
          key={view.key}
          pressed={view.key === activeKey}
          onPressedChange={() => onSelect(view.key)}
          aria-label={view.label}
          // Fixed square across every chip — only the inner content size varies.
          className="size-[34px] p-0"
        >
          {view.kind === "account" ? (
            // Account view: the user avatar with the platform brand mark notched on it.
            <UserAvatar
              name={view.descriptor.account.username}
              src={view.descriptor.account.avatarUrl}
              size="sm"
              className="size-[32px] [&_[data-slot=avatar-fallback]]:text-[0.5rem]! [&_[data-slot=avatar-fallback]]:leading-none!"
            >
              {/* A bordered disc (not a knockout) so the mark reads on the transparent
                  chip even where it straddles off the avatar. The explicit brand-mark
                  size opts it out of the Toggle's [&_svg]:size-4 auto-sizing. */}
              {view.platform ? (
                <UserAvatarBadge className="[&>*]:ring-0">
                  <span className="flex size-3 items-center justify-center rounded-full border border-border bg-background">
                    <BrandMark platform={view.platform} className="size-2" />
                  </span>
                </UserAvatarBadge>
              ) : null}
            </UserAvatar>
          ) : view.platform ? (
            // Platform view: the platform brand mark only.
            <BrandMark platform={view.platform} className="size-5" />
          ) : (
            // Placeholder view (bare-id account): a generic user glyph, no platform mark.
            <User className="size-5 text-muted-foreground"
              aria-hidden />
          )}
        </Toggle>
      ))}
    </div>
  );
}

/**
 * The smart chrome dispatcher — internal machinery of {@link SocialPostPreview}. Resolves the
 * frame's `(platform, surface)` and maps the resolved descriptor onto that surface's primitives
 * (e.g. `TikTokPost` + `TikTokPostMedia` + `TikTokPostUI`). Reads the current frame from context
 * (as SocialPostPreview provides it) or takes an explicit `descriptor`. This is the ONLY place a
 * post is auto-mapped onto primitives — the per-surface primitives themselves are pure.
 */
export function SocialPostPreviewChrome({
  descriptor: descriptorProp,
}: {
  /** Render this frame explicitly instead of reading the current frame context. */
  descriptor?: SocialPostPreviewDescriptor;
}) {
  const frame = useSocialPostPreviewFrame();
  const descriptor = descriptorProp ?? frame;
  if (!descriptor) return null;

  // A placeholder frame (an account passed as a bare id — platform unknown) gets a neutral
  // card, not a platform chrome.
  if (descriptor.placeholder) {
    return <SocialPostPreviewChromePlaceholder descriptor={descriptor} />;
  }

  switch (descriptor.platform) {
    case "x": {
      const { account, caption, media, quote } = descriptor;
      return (
        <XPost
          username={account.username}
          displayName={account.displayName ?? undefined}
          avatarSrc={account.avatarUrl ?? undefined}
          caption={caption}
        >
          {media.length > 0 ? <XPostMedia media={media} /> : null}
          {quote ? (
            quote.placeholder ? (
              <XPostQuote placeholder />
            ) : (
              <XPostQuote
                username={quote.username}
                displayName={quote.displayName}
                avatarSrc={quote.avatarUrl}
                caption={quote.caption}
                media={quote.media}
              />
            )
          ) : null}
        </XPost>
      );
    }
    case "tiktok":
    case "tiktok_business": {
      const media = descriptor.media[0];
      return (
        <TikTokPost>
          <TikTokPostMedia
            imageSrc={media?.kind === "image" ? media.src : undefined}
            videoSrc={media?.kind === "video" ? media.videoSrc : undefined}
            thumbnailSrc={media?.kind === "video" ? media.src : undefined}
          />
          <TikTokPostUI
            username={descriptor.account.username}
            displayName={descriptor.account.displayName ?? undefined}
            avatarSrc={descriptor.account.avatarUrl ?? undefined}
            caption={descriptor.caption}
          />
        </TikTokPost>
      );
    }
    case "instagram": {
      const { account, caption, media } = descriptor;
      if (descriptor.surface === "reel") {
        const m = media[0];
        return (
          <InstagramReel>
            <InstagramReelMedia
              imageSrc={m?.kind === "image" ? m.src : undefined}
              videoSrc={m?.kind === "video" ? m.videoSrc : undefined}
              thumbnailSrc={m?.kind === "video" ? m.src : undefined}
            />
            <InstagramReelUI
              username={account.username}
              displayName={account.displayName ?? undefined}
              avatarSrc={account.avatarUrl ?? undefined}
              caption={caption}
            />
          </InstagramReel>
        );
      }
      if (descriptor.surface === "story") {
        // A story can carry several media — rotate through them (segmented progress + tap).
        return (
          <StoryRotator
            frame={InstagramStory}
            mediaLayer={InstagramStoryMedia}
            ui={InstagramStoryUI}
            items={media}
            username={account.username}
            displayName={account.displayName ?? undefined}
            avatarSrc={account.avatarUrl ?? undefined}
            caption={caption}
          />
        );
      }
      return (
        <InstagramPost
          username={account.username}
          displayName={account.displayName ?? undefined}
          avatarSrc={account.avatarUrl ?? undefined}
          caption={caption}
        >
          {media.length > 0 ? <InstagramPostMedia media={media} /> : null}
        </InstagramPost>
      );
    }
    case "facebook": {
      const { account, caption, media } = descriptor;
      if (descriptor.surface === "reel") {
        const m = media[0];
        return (
          <FacebookReel>
            <FacebookReelMedia
              imageSrc={m?.kind === "image" ? m.src : undefined}
              videoSrc={m?.kind === "video" ? m.videoSrc : undefined}
              thumbnailSrc={m?.kind === "video" ? m.src : undefined}
            />
            <FacebookReelUI
              username={account.username}
              displayName={account.displayName ?? undefined}
              avatarSrc={account.avatarUrl ?? undefined}
              caption={caption}
            />
          </FacebookReel>
        );
      }
      if (descriptor.surface === "story") {
        // A story can carry several media — rotate through them (segmented progress + tap).
        return (
          <StoryRotator
            frame={FacebookStory}
            mediaLayer={FacebookStoryMedia}
            ui={FacebookStoryUI}
            items={media}
            username={account.username}
            displayName={account.displayName ?? undefined}
            avatarSrc={account.avatarUrl ?? undefined}
            caption={caption}
          />
        );
      }
      return (
        <FacebookPost
          username={account.username}
          displayName={account.displayName ?? undefined}
          avatarSrc={account.avatarUrl ?? undefined}
          caption={caption}
        >
          {media.length > 0 ? <FacebookPostMedia media={media} /> : null}
        </FacebookPost>
      );
    }
    case "youtube":
      // Video vs. Short is sniffed from the cover's orientation (YouTube has no API flag).
      return <YouTubeChrome descriptor={descriptor} />;
    case "linkedin": {
      const { account, caption, media } = descriptor;
      return (
        <LinkedInPost
          username={account.username}
          displayName={account.displayName ?? undefined}
          avatarSrc={account.avatarUrl ?? undefined}
          caption={caption}
        >
          {media.length > 0 ? <LinkedInPostMedia media={media} /> : null}
        </LinkedInPost>
      );
    }
    case "pinterest": {
      const { account, caption, media } = descriptor;
      const cover = media[0];
      return (
        <PinterestPin
          username={account.username}
          displayName={account.displayName ?? undefined}
          avatarSrc={account.avatarUrl ?? undefined}
          caption={caption}
        >
          <PinterestPinMedia
            imageSrc={cover?.kind === "image" ? cover.src : undefined}
            videoSrc={cover?.kind === "video" ? cover.videoSrc : undefined}
            thumbnailSrc={cover?.kind === "video" ? cover.src : undefined}
          />
        </PinterestPin>
      );
    }
    case "threads": {
      const { account, caption, media } = descriptor;
      return (
        <ThreadsPost
          username={account.username}
          displayName={account.displayName ?? undefined}
          avatarSrc={account.avatarUrl ?? undefined}
          caption={caption}
        >
          {media.length > 0 ? <ThreadsPostMedia media={media} /> : null}
        </ThreadsPost>
      );
    }
    case "bluesky": {
      const { account, caption, media } = descriptor;
      return (
        <BlueskyPost
          username={account.username}
          displayName={account.displayName ?? undefined}
          avatarSrc={account.avatarUrl ?? undefined}
          caption={caption}
        >
          {media.length > 0 ? <BlueskyPostMedia media={media} /> : null}
        </BlueskyPost>
      );
    }
    default:
      return <SocialPostPreviewChromeFallback descriptor={descriptor} />;
  }
}

/**
 * Sniff a cover's orientation on the client (portrait? → true). The natural size is read from a
 * throwaway `Image` / `<video>` — the same still the media item would show — so the caller needs
 * no measurement hook on the rendered primitive. Landscape until it loads; SSR-safe (the effect
 * is client-only). Keyed on the media's URLs so it re-measures when the cover changes.
 */
function useCoverIsPortrait(media?: SocialPostPreviewMedia): boolean {
  const [portrait, setPortrait] = useState(false);
  const still = media?.src;
  const videoSrc = media?.kind === "video" ? media.videoSrc : undefined;

  useEffect(() => {
    let cancelled = false;
    const decide = (width: number, height: number) => {
      if (!cancelled && width && height) setPortrait(height > width);
    };
    // Poster still (image, or a video's thumbnail) → measure the image; a posterless video →
    // read its metadata. Mirrors how SocialPostPreviewMediaItem resolves the same media.
    if (still) {
      const img = new Image();
      img.onload = () => decide(img.naturalWidth, img.naturalHeight);
      img.src = still;
    } else if (videoSrc) {
      const video = document.createElement("video");
      video.preload = "metadata";
      video.onloadedmetadata = () => decide(video.videoWidth, video.videoHeight);
      video.src = videoSrc;
    }
    return () => {
      cancelled = true;
    };
  }, [still, videoSrc]);

  return portrait;
}

/**
 * YouTube's surface picker — the API has no short/video flag, so (like the real product) the
 * mapping decides contextually: portrait cover → the vertical Short, else the landscape Video
 * (watch) page. The `YouTube*` primitives are unopinionated (either can be rendered at any time);
 * this mapper-layer component owns the orientation logic and measures the cover itself.
 */
function YouTubeChrome({
  descriptor,
}: {
  descriptor: SocialPostPreviewDescriptor;
}) {
  const { account, caption, media } = descriptor;
  const cover = media[0];
  const portrait = useCoverIsPortrait(cover);

  if (portrait) {
    return (
      <YouTubeShort>
        <YouTubeShortMedia
          imageSrc={cover?.kind === "image" ? cover.src : undefined}
          videoSrc={cover?.kind === "video" ? cover.videoSrc : undefined}
          thumbnailSrc={cover?.kind === "video" ? cover.src : undefined}
        />
        <YouTubeShortUI
          username={account.username}
          displayName={account.displayName ?? undefined}
          avatarSrc={account.avatarUrl ?? undefined}
          caption={caption}
        />
      </YouTubeShort>
    );
  }
  return (
    <YouTubeVideo
      username={account.username}
      displayName={account.displayName ?? undefined}
      avatarSrc={account.avatarUrl ?? undefined}
      caption={caption}
    >
      <YouTubeVideoMedia
        imageSrc={cover?.kind === "image" ? cover.src : undefined}
        videoSrc={cover?.kind === "video" ? cover.videoSrc : undefined}
        thumbnailSrc={cover?.kind === "video" ? cover.src : undefined}
      />
    </YouTubeVideo>
  );
}

/** A neutral placeholder for platforms/surfaces without a concrete chrome yet. */
function SocialPostPreviewChromeFallback({
  descriptor,
}: {
  descriptor: SocialPostPreviewDescriptor;
}) {
  return (
    <div
      data-slot="social-post-preview-chrome-fallback"
      data-surface={descriptor.surface}
      className="flex h-full flex-col items-center justify-center gap-[0.4em] bg-muted p-[0.9em] text-center leading-snug text-muted-foreground"
    >
      {descriptor.platform ? (
        <BrandMark platform={descriptor.platform} className="size-[2em]" />
      ) : null}
      <span className="font-medium">{descriptor.platform}</span>
      <span className="text-[0.8em]">
        {descriptor.surface} · preview coming soon
      </span>
    </div>
  );
}

/**
 * A neutral post card for a **placeholder** frame — an account handed in as a bare id, so
 * its platform is unknown. Identity is dummy-filled; we still show the post's caption and
 * media so the preview is useful. Pass the full account object to upgrade to the real chrome.
 */
function SocialPostPreviewChromePlaceholder({
  descriptor,
}: {
  descriptor: SocialPostPreviewDescriptor;
}) {
  const { caption, media } = descriptor;
  const cover = media[0];

  return (
    <div
      data-slot="social-post-preview-chrome-placeholder"
      data-surface="placeholder"
      className="flex h-full flex-col bg-background leading-snug"
    >
      {/* header — skeleton identity (a bare id string carries no name / avatar) */}
      <div className="flex items-center gap-[0.6em] p-[0.9em]">
        <Skeleton className="size-[2.4em] shrink-0 rounded-full" />
        <div className="flex min-w-0 flex-col gap-[0.35em]">
          <Skeleton className="h-[0.85em] w-[7em] rounded-full" />
          <Skeleton className="h-[0.75em] w-[5em] rounded-full" />
        </div>
      </div>

      {/* caption */}
      {caption ? (
        <p className="px-[0.9em] pb-[0.7em] break-words whitespace-pre-wrap">
          {caption}
        </p>
      ) : null}

      {/* media */}
      {cover ? (
        <div className="relative aspect-square bg-muted">
          <SocialPostPreviewMediaItem media={cover} />
        </div>
      ) : null}
    </div>
  );
}

// ── Re-exports — the raw building blocks, for hand-composing without a second import path.
export { SocialPostPreviewDevice } from "./social-post-preview-device";
export { SocialPostPreviewFeed } from "./social-post-preview-feed-skeleton";
export { SocialPostPreviewMediaItem } from "./social-post-preview-media";
export {
  SocialPostPreviewFrameProvider,
  useSocialPostPreviewFrame,
} from "./social-post-preview-context";
export { useSocialPostPreview } from "~/hooks/use-social-post-preview";
export {
  resolveSocialPost,
  resolveSocialPostViews,
  type SocialPostPreviewView,
} from "~/lib/social-post-preview-resolver";
export type {
  SocialPostPreviewAccount,
  SocialPostPreviewAccountRef,
  SocialPostPreviewDescriptor,
  SocialPostPreviewDeviceKind,
  SocialPostPreviewFrameAccount,
  SocialPostPreviewInput,
  SocialPostPreviewMedia,
  SocialPostPreviewMediaInput,
  SocialPostPreviewQuoteRef,
  SocialPostPreviewSurface,
} from "~/lib/social-post-preview-types";

"use client";

import type { ComponentProps, ComponentType, ReactNode } from "react";
import { useEffect, useState } from "react";

import { cn } from "~/lib/utils";
import { ArrowLeft, ArrowRight } from "lucide-react";
import type { SocialPostPreviewMedia } from "~/lib/social-post-preview-types";

/**
 * Rotation state for a multi-story post. A Post for Me "story" can carry several media — each is
 * published as its own story — so the preview rotates through them like the real app: manual
 * tap (see {@link StoryTapZones}) and, when `autoAdvance` is on, a timer that advances every
 * `intervalMs` and loops. Auto-advance is skipped under `prefers-reduced-motion`.
 */
export function useStoryRotation(
  count: number,
  { autoAdvance = false, intervalMs = 4000 }: { autoAdvance?: boolean; intervalMs?: number } = {},
) {
  const total = Math.max(1, count);
  const [activeIndex, setActiveIndex] = useState(0);

  // Keep the index in range if the media set shrinks.
  useEffect(() => {
    setActiveIndex((i) => Math.min(i, total - 1));
  }, [total]);

  // Next loops (last → first); back is a dead-end at the first story (clamped, no wrap).
  const next = () => setActiveIndex((i) => (i + 1) % total);
  const prev = () => setActiveIndex((i) => Math.max(0, i - 1));

  useEffect(() => {
    if (!autoAdvance || total <= 1) return;
    const reduce =
      typeof window !== "undefined" &&
      window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    if (reduce) return;
    const timer = setInterval(
      () => setActiveIndex((i) => (i + 1) % total),
      intervalMs,
    );
    return () => clearInterval(timer);
  }, [autoAdvance, total, intervalMs]);

  return { activeIndex, next, prev };
}

/**
 * Full-bleed tap targets over the story — left third goes back, the rest advances (like IG/FB).
 * On the first story (`canPrev` false) there's nothing before it, so the whole area advances.
 */
export function StoryTapZones({
  onPrev,
  onNext,
  canPrev = true,
}: {
  onPrev: () => void;
  onNext: () => void;
  canPrev?: boolean;
}) {
  return (
    <div className="absolute inset-0 z-10 flex">
      {canPrev ? (
        <button
          type="button"
          aria-label="Previous story"
          onClick={onPrev}
          className="h-full w-1/3 cursor-pointer focus:outline-none"
        />
      ) : null}
      <button
        type="button"
        aria-label="Next story"
        onClick={onNext}
        className="h-full flex-1 cursor-pointer focus:outline-none"
      />
    </div>
  );
}

/**
 * A preview-only affordance: an edge arrow hinting "tap here for the previous / next story",
 * with a subtle horizontal nudge so the tap action reads at a glance. Decorative
 * (pointer-events-none) so the tap lands on {@link StoryTapZones} beneath it; the nudge is
 * `motion-safe` only.
 */
export function StoryAdvanceHint({
  direction = "next",
  hidden = false,
}: {
  direction?: "next" | "prev";
  /** Keep it mounted (so its bounce stays in phase with the other arrow) but not shown. */
  hidden?: boolean;
}) {
  const prev = direction === "prev";
  return (
    <span
      aria-hidden
      className={cn(
        "pointer-events-none absolute top-1/2 z-20 -translate-y-1/2",
        prev ? "left-[0.6em]" : "right-[0.6em]",
        hidden && "invisible",
      )}
    >
      <span
        className={cn(
          "grid size-[1.9em] place-items-center rounded-full bg-white/75 text-black [&_svg]:size-[1.1em]",
          // One shared keyframe + `animate-*` utility (shipped via the item's css/cssVars,
          // mirrored in app.css); direction is a CSS var so prev nudges the other way.
          "motion-safe:animate-social-post-story-arrow",
          prev && "[--social-post-story-arrow-dir:-1]",
        )}
      >
        {prev ? (
          <ArrowLeft />
        ) : (
          <ArrowRight />
        )}
      </span>
    </span>
  );
}

/**
 * Composes a platform's story primitives (frame + media + UI) into a **rotating** story: it owns
 * the active index, feeds `count`/`activeIndex` to the UI's segmented progress bar, shows the
 * current media, and — when there's more than one — adds the tap zones + the next-story hint.
 * Shared by every story surface; the frame/media/ui are passed in so the same logic drives
 * Instagram, Facebook, etc.
 */
export function StoryRotator({
  frame: Frame,
  mediaLayer: MediaLayer,
  ui: UILayer,
  items,
  username,
  displayName,
  avatarSrc,
  caption,
  autoAdvance = false,
}: {
  frame: ComponentType<ComponentProps<"div"> & { children?: ReactNode }>;
  mediaLayer: ComponentType<{
    imageSrc?: string;
    videoSrc?: string;
    thumbnailSrc?: string;
  }>;
  ui: ComponentType<{
    username?: string;
    displayName?: string;
    avatarSrc?: string;
    caption?: string;
    count?: number;
    activeIndex?: number;
  }>;
  items: SocialPostPreviewMedia[];
  username?: string;
  displayName?: string;
  avatarSrc?: string;
  caption?: string;
  autoAdvance?: boolean;
}) {
  const { activeIndex, next, prev } = useStoryRotation(items.length, {
    autoAdvance,
  });
  const current = items[activeIndex];
  const multi = items.length > 1;

  return (
    <Frame>
      <MediaLayer
        imageSrc={current?.kind === "image" ? current.src : undefined}
        videoSrc={current?.kind === "video" ? current.videoSrc : undefined}
        thumbnailSrc={current?.kind === "video" ? current.src : undefined}
      />
      <UILayer
        username={username}
        displayName={displayName}
        avatarSrc={avatarSrc}
        caption={caption}
        count={items.length}
        activeIndex={activeIndex}
      />
      {multi ? (
        <>
          <StoryTapZones
            onPrev={prev}
            onNext={next}
            canPrev={activeIndex > 0}
          />
          {/* Both arrows stay mounted so their bounces share one clock; the back arrow is just
              hidden on the first story (nothing before it). */}
          <StoryAdvanceHint direction="prev" hidden={activeIndex === 0} />
          <StoryAdvanceHint direction="next" />
        </>
      ) : null}
    </Frame>
  );
}

import type { ComponentProps, ReactNode } from "react";

import { cn } from "~/lib/utils";

/**
 * The device frame a preview renders inside — a phone. Two jobs:
 *
 * 1. **Clips the chrome to one rounded shape.** The screen owns the corner radius +
 *    `overflow-hidden`; content fills it and is clipped. The bezel is a SEPARATE outer body
 *    (padding + `bg-foreground`), NOT a `border` on the clipping element — a border + radius +
 *    overflow doesn't nest cleanly, so the bezel/screen boundary leaked the screen's `bg` as a
 *    white crescent at the corners (visible against a chrome's dark edge, e.g. YouTube's black
 *    bar). Bezel radius (`13cqi`) and screen radius (`10.5cqi`) are **concentric** (outer −
 *    padding), so they nest exactly.
 * 2. **Owns the scale.** The OUTER element is the container-query context (`container-type:
 *    inline-size`); everything below sizes off it. The screen sets a container-relative base
 *    font (`text-[4cqi]`) so every chrome sizes its text / padding / spacing in `em` and scales
 *    with the frame at any width — never a fixed px. Radii + padding are `cqi` too, so they stay
 *    the same *fraction* of the frame at every size. All `cqi` values live on children of the
 *    container, never the container itself: `cqi` resolves against the nearest *ancestor*
 *    container, so on the container element it would fall back to the viewport.
 *
 * The frame is the **lowest-fidelity phone mock**: a chunky `bg-foreground` bezel and heavily
 * rounded corners. **No shadow** on purpose — `className` is forwarded to the bezel, so a
 * consumer adds their own elevation (`shadow-*`) and it follows the rounded shape. The screen
 * (inner content) radius ≈10.5cqi (≈2.6em) — the clearance the full-bleed chromes' corner
 * overlays are tuned against. No dynamic island. One style for now; this is the seam where
 * browser / bare / other device styles drop in later (a `variant`, then per-style files).
 */
export function SocialPostPreviewDevice({
  className,
  children,
  ...props
}: {
  children?: ReactNode;
} & ComponentProps<"div">) {
  return (
    <div className="relative mx-auto w-full max-w-64 select-none [container-type:inline-size]">
      <div
        data-slot="social-post-preview-device"
        className={cn(
          "rounded-[13cqi] bg-foreground p-[2.5cqi]",
          className,
        )}
        {...props}
      >
        {/* The SCREEN owns the aspect (`9/19.5`) — the bezel wraps it with `cqi` padding, so
            the content area (and thus a full-bleed chrome) is exactly this ratio and fills it
            with no gap. Putting the aspect on the outer instead left the padded screen a
            slightly different ratio, and vertical chromes didn't fill. */}
        <div
          data-slot="social-post-preview-screen"
          className="aspect-[9/19.5] overflow-hidden rounded-[10.5cqi] bg-background text-[4cqi]"
        >
          {children}
        </div>
      </div>
    </div>
  );
}

"use client";

import type { ReactNode } from "react";
import { createContext, useContext } from "react";

import type { SocialPostPreviewDescriptor } from "~/lib/social-post-preview-types";

const SocialPostPreviewFrameContext =
  createContext<SocialPostPreviewDescriptor | null>(null);

/**
 * Scopes one {@link SocialPostPreviewDescriptor} to a single frame's subtree, so the
 * device + chrome render that account's post. {@link SocialPostPreview} wraps
 * each frame in one; a consumer hand-composing frames can too.
 */
export function SocialPostPreviewFrameProvider({
  descriptor,
  children,
}: {
  descriptor: SocialPostPreviewDescriptor;
  children: ReactNode;
}) {
  return (
    <SocialPostPreviewFrameContext.Provider value={descriptor}>
      {children}
    </SocialPostPreviewFrameContext.Provider>
  );
}

/**
 * Read the current frame's descriptor, or `null` outside a frame. Nullable by design:
 * a chrome may instead take an explicit `descriptor` prop (the manual escape hatch).
 */
export function useSocialPostPreviewFrame(): SocialPostPreviewDescriptor | null {
  return useContext(SocialPostPreviewFrameContext);
}

import type { ReactNode } from "react";

import { cn } from "~/lib/utils";
import { Skeleton } from "~/ui/skeleton";

/**
 * The **feed context** — a masked timeline of skeleton posts wrapped around a real post. This
 * is a COMPOSED layer, not baked into the chromes: a bare post (e.g. `XPost`)
 * renders just the post, so a consumer can drop it into their own card / border. The
 * auto-renderer wraps feed-surface chromes in this to make the phone read like a real timeline.
 */
export function SocialPostPreviewFeed({
  children,
  className,
}: {
  children: ReactNode;
  className?: string;
}) {
  return (
    <div
      data-slot="social-post-preview-feed"
      className={cn(
        "flex h-full flex-col divide-y divide-border bg-background leading-snug",
        "[&_[data-slot=skeleton]]:animate-none",
        // Fade the feed's edges so the skeleton context softens away (top 10%, bottom 25%).
        "[-webkit-mask-image:linear-gradient(to_bottom,transparent,#000_10%,#000_75%,transparent)]",
        "[mask-image:linear-gradient(to_bottom,transparent,#000_10%,#000_75%,transparent)]",
        className,
      )}
    >
      <FeedTailSkeleton />
      {children}
      <FeedPostSkeleton />
    </div>
  );
}

/**
 * Shared feed-context skeletons for the timeline chromes (Facebook / LinkedIn / Threads /
 * Bluesky). The previewed post sits between a **tail** (the bottom of the previous post,
 * peeking in up top so the real post stays centered) and a **full** post below. Shapes are
 * the shadcn {@link Skeleton} primitive; the wrapper dims them to 65% so the context stays
 * quiet. Feed chromes mask the top/bottom edges so this fades away.
 */
export function FeedTailSkeleton({ className }: { className?: string }) {
  return (
    <div
      className={cn("flex shrink-0 flex-col p-[0.9em] opacity-65", className)}
      aria-hidden
    >
      <div className="flex items-center gap-[0.6em]">
        <Skeleton className="h-[0.7em] w-[45%] rounded-full" />
      </div>
      <div className="mt-[0.5em] space-y-[0.35em]">
        <Skeleton className="h-[0.7em] w-[92%] rounded-full" />
        <Skeleton className="h-[0.7em] w-[60%] rounded-full" />
      </div>
      <div className="mt-[0.7em] flex items-center gap-[1.4em]">
        <Skeleton className="h-[0.9em] w-[3.5em] rounded-full" />
        <Skeleton className="h-[0.9em] w-[3.5em] rounded-full" />
        <Skeleton className="h-[0.9em] w-[3.5em] rounded-full" />
      </div>
    </div>
  );
}

